<?php $title='Customer Registration'; require __DIR__.'/../includes/header.php'; require __DIR__.'/../config/database.php'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??''; if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6){$error='Enter valid details. Password must be at least 6 characters.';} else {try{$st=$pdo->prepare("INSERT INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?, 'customer')");$st->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);redirect(BASE_URL.'auth/login.php');}catch(PDOException $e){$error='Email may already be registered.';}}} ?>
<section class="section-pad"><div class="container"><div class="row justify-content-center"><div class="col-md-7 col-lg-6"><div class="card border-0 shadow-sm p-4 rounded-4"><h2 class="fw-bold">Create account</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input class="form-control mb-3" name="name" placeholder="Full name" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" name="phone" placeholder="Mobile number" required><input class="form-control mb-3" type="password" name="password" placeholder="Password (6+ characters)" required><button class="btn btn-warning w-100 fw-bold">Register</button></form></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>